  effects pure
  example take([1, 2, 3], 2) == [1, 2]
  example take([1, 2, 3], 0) == []
{
  if n == 0 then [] else match xs {
    [] => []
    [h, ..t] => [h] ++ take(t, n - 1)
  }
}

